// === REPARO DE ESTRUTURA: chaves fora de translations ===
// Espelha exatamente o normalizeLocaleMessages do index.js (deepMerge em que o
// bloco de FORA vence), só que antes das traduções complementares, para que
// elas vejam a estrutura final. Depois disto o index.js não tem mais o que
// mesclar, então o resultado na tela é o mesmo de antes.
(function () {
  const L = messages.ar;
  const merge = (t, s) => {
    for (const k of Object.keys(s)) {
      if (t[k] && typeof t[k] === "object" && !Array.isArray(t[k]) &&
          s[k] && typeof s[k] === "object" && !Array.isArray(s[k])) merge(t[k], s[k]);
      else t[k] = s[k];
    }
  };
  for (const k of Object.keys(L)) {
    if (k === "translations") continue;
    merge(L.translations, { [k]: L[k] });
    delete L[k];
  }
})();

